create table if not exists public.gymflow_profiles (id uuid primary key references auth.users(id) on delete cascade, role text not null check (role in ('owner','member')), gym_id text not null, member_id text, name text not null default '', phone text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.gymflow_records (id text primary key, gym_id text not null, record_type text not null, payload jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists gymflow_records_gym_type_idx on public.gymflow_records(gym_id, record_type);
create index if not exists gymflow_records_member_idx on public.gymflow_records(gym_id, ((payload->>'memberId')));
alter table public.gymflow_profiles enable row level security;
alter table public.gymflow_records enable row level security;
grant select, insert, update on public.gymflow_profiles to authenticated;
grant select, insert, update, delete on public.gymflow_records to authenticated;
create policy profiles_self_select on public.gymflow_profiles for select to authenticated using ((select auth.uid()) = id);
create policy profiles_self_insert on public.gymflow_profiles for insert to authenticated with check ((select auth.uid()) = id);
create policy profiles_self_update on public.gymflow_profiles for update to authenticated using ((select auth.uid()) = id) with check ((select auth.uid()) = id);
create policy records_owner_all on public.gymflow_records for all to authenticated using (exists (select 1 from public.gymflow_profiles p where p.id=(select auth.uid()) and p.role='owner' and p.gym_id=gymflow_records.gym_id)) with check (exists (select 1 from public.gymflow_profiles p where p.id=(select auth.uid()) and p.role='owner' and p.gym_id=gymflow_records.gym_id));
create policy records_member_select on public.gymflow_records for select to authenticated using (exists (select 1 from public.gymflow_profiles p where p.id=(select auth.uid()) and p.role='member' and p.gym_id=gymflow_records.gym_id) and (record_type in ('gyms','plans','workouts','diets') or ((select member_id from public.gymflow_profiles where id=(select auth.uid())) = payload->>'id') or ((select member_id from public.gymflow_profiles where id=(select auth.uid())) = payload->>'memberId')));
create policy records_member_insert on public.gymflow_records for insert to authenticated with check (exists (select 1 from public.gymflow_profiles p where p.id=(select auth.uid()) and p.role='member' and p.gym_id=gymflow_records.gym_id) and ((record_type='members' and (select member_id from public.gymflow_profiles where id=(select auth.uid())) = payload->>'id') or (record_type='attendance' and (select member_id from public.gymflow_profiles where id=(select auth.uid())) = payload->>'memberId')));
create policy records_member_update on public.gymflow_records for update to authenticated using (exists (select 1 from public.gymflow_profiles p where p.id=(select auth.uid()) and p.role='member' and p.gym_id=gymflow_records.gym_id) and ((record_type='members' and (select member_id from public.gymflow_profiles where id=(select auth.uid())) = payload->>'id') or (record_type='attendance' and (select member_id from public.gymflow_profiles where id=(select auth.uid())) = payload->>'memberId'))) with check (exists (select 1 from public.gymflow_profiles p where p.id=(select auth.uid()) and p.role='member' and p.gym_id=gymflow_records.gym_id) and ((record_type='members' and (select member_id from public.gymflow_profiles where id=(select auth.uid())) = payload->>'id') or (record_type='attendance' and (select member_id from public.gymflow_profiles where id=(select auth.uid())) = payload->>'memberId')));
